import{_ as l,a0 as i,w as s,s as e,I as u,x as n,a1 as o,A as r,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何双启动 Ubuntu 22.04 LTS 和 Windows 11 | LCTT x X-CMD","titleTemplate":false,"description":"如何双启动 Ubuntu 22.04 LTS 和 Windows 11 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何双启动 Ubuntu 22.04 LTS 和 Windows 11 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何双启动 Ubuntu 22.04 LTS 和 Windows 11 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220516 How to Dual Boot Ubuntu 22.04 LTS and Windows 11","title":"如何双启动 Ubuntu 22.04 LTS 和 Windows 11","tag":"202206","desc":""},"relativePath":"202206/20220516 How to Dual Boot Ubuntu 22.04 LTS and Windows 11.md","filePath":"[post].md"}'),w={name:"202206/20220516 How to Dual Boot Ubuntu 22.04 LTS and Windows 11.md"};function b(d,t,m,c,g,U){const p=i("Link");return s(),e("div",null,[t[19]||(t[19]=u("h1",{id:"如何双启动-ubuntu-22-04-lts-和-windows-11",tabindex:"-1"},[n("如何双启动 Ubuntu 22.04 LTS 和 Windows 11 "),u("a",{class:"header-anchor",href:"#如何双启动-ubuntu-22-04-lts-和-windows-11","aria-label":"Permalink to “如何双启动 Ubuntu 22.04 LTS 和 Windows 11”"},"​")],-1)),t[20]||(t[20]=u("p",null,[u("img",{src:"https://img.linux.net.cn/data/attachment/album/202206/12/110546fff10ck07e2p0z2f.jpg",alt:""})],-1)),t[21]||(t[21]=u("p",null,"嗨，伙计们，在这篇指南中，我们将演示如何在 Windows 11 的之外配置 Ubuntu 22.04 LTS（Jammy Jellyfish）的双启动设置。",-1)),t[22]||(t[22]=u("p",null,"为使其能工作，你需要在你的计算机上已经安装好了 Windows 11 。接下来，你将需要在你的硬盘驱动器上创建一个单独的分区，你将在此分区上安装 Ubuntu 22.04 。我们将包含这点知识，因此不要担心。",-1)),t[23]||(t[23]=u("p",null,[u("strong",null,"前置条件：")],-1)),t[24]||(t[24]=u("p",null,"在设置双启动前，这些是你所需要的：",-1)),u("ul",null,[u("li",null,[t[1]||(t[1]=n("一个 Ubuntu 22.04 的可启动 USB 驱动器，你可以转到 ",-1)),o(p,{href:"https://releases.ubuntu.com/22.04/"},{default:r(()=>[...t[0]||(t[0]=[n("Ubuntu 22.04 下载页面",-1)])]),_:1}),t[2]||(t[2]=n(" 来下载 Ubuntu 22.04 的 ISO 镜像文件。在 ISO 镜像文件到位后，拿一个 16GB USB 驱动器，并使用 Rufus 应用程序来使其可启动。",-1))]),t[3]||(t[3]=u("li",null,"快速稳定的互联网连接",-1))]),t[25]||(t[25]=a('<h3 id="步骤-1、在你的硬盘驱动器上创建一个可用的分区" tabindex="-1">步骤 1、在你的硬盘驱动器上创建一个可用的分区 <a class="header-anchor" href="#步骤-1、在你的硬盘驱动器上创建一个可用的分区" aria-label="Permalink to “步骤 1、在你的硬盘驱动器上创建一个可用的分区”">​</a></h3><p>正如介绍中所提到的，我们首先需要在硬盘驱动器上创建一个单独的分区，我们将在其中安装 Ubuntu 22.04 。</p><p>因此，通过按下 <code>Windows + R</code> 组合键来打开磁盘管理器实用程序。</p><p>在对话框中，输入 <code>diskmgmt.msc</code> ，并按下回车键。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/diskmgmt-msc-command-windows11.png" alt=""></p><p><ruby>磁盘管理<rt>disk management</rt></ruby>控制台将显示当前磁盘分区，如你将在下面所看到的一样。我们将通过压缩 “卷 E” 来创建一个用于安装 Ubuntu 的分区。这在你的安装过程中可能有所不同，但是只需要跟着做，你就会理解其中的大体意思。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Disk-Management-Console-Windows11.png" alt=""></p><p>因此，在你想要压缩的磁盘驱动器卷上点击鼠标右键，并在弹出的菜单中选择 <ruby>压缩卷<rt>Shrink</rt></ruby> 选项。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Shrink-Volume-Windows11.png" alt=""></p><p>将会出现一个弹出对话框，如下所示。具体指定压缩的控件大小（以 MB 为单位），并单击 <ruby>压缩卷<rt>Shrink</rt></ruby> 。</p><p>这是指定给 Ubuntu 22.04 安装所用的空间。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Shrink-Volume-Size-Windows11.png" alt=""></p><p>在缩小磁盘空间后，它将显示为 <ruby>未分配<rt>Unallocated</rt></ruby> 或 <ruby>可用空间<rt>Free Space</rt></ruby>，如图所示。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Free-Space-Disk-Management-Console-Windows11.png" alt=""></p><p>随着有了可用空间，现在将可启动 USB 驱动器插入到你的 PC ，并重新启动你的系统。此外，要确保访问 BIOS 设置，并修改启动优先级，来使 USB 驱动器成为第一优先级。保存 BIOS 更改并继续启动。</p><h3 id="步骤-2、开始安装" tabindex="-1">步骤 2、开始安装 <a class="header-anchor" href="#步骤-2、开始安装" aria-label="Permalink to “步骤 2、开始安装”">​</a></h3><p>在第一个屏幕中，你将得到如图所示的 GRUB 菜单。选择第一个选项 <ruby>尝试或安装 Ubuntu<rt>Try or Install Ubuntu</rt></ruby> ，并按下 <ruby>回车键<rt>ENTER</rt></ruby> 按键。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Select-Install-Ubuntu-Linux.png" alt=""></p><p>Ubuntu 22.04 将开始加载，如下所示。这最多需要一分钟。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Ubuntu-22-04-Loading-Screen.png" alt=""></p><p>此后，安装程序向导将弹出，向你提供两个选项： <ruby>尝试 Ubuntu<rt>Try Ubuntu</rt></ruby> 和 <ruby>安装 Ubuntu<rt>Install Ubuntu</rt></ruby>。因为我们的使命是安装 Ubuntu ，所以选择后者。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Choose-Install-Ubuntu-Linux.png" alt=""></p><p>接下来，选择你的首选键盘布局，并单击 <ruby>继续<rt>Continue</rt></ruby> 按钮。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Keyboard-Layout-Ubuntu-22-04.png" alt=""></p><p>在 <ruby>更新和其它软件<rt>Updates and Other Software</rt></ruby> 步骤中，选择 <ruby>正常安装<rt>Normal Installation</rt></ruby> 以便安装 Ubuntu的 GUI 版本，通过勾选其它剩余选项来允许下载更新和安装第三方的针对于图像、WIFI 硬件和其它实用程序的软件包。</p><p>接下来，单击 <ruby>继续<rt>Continue</rt></ruby> 按钮。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Normal-Installation-Option-During-Ubuntu-22-04-Installation.png" alt=""></p><p>下一步提供两个安装选项。第一个选项 - <ruby>清除整个磁盘并安装 Ubuntu<rt>Erase disk and install Ubuntu</rt></ruby> – 完全地擦除你的驱动器并安装。但是由于这是一个双启动设置，这个选项对于你现有安装的 Windows 系统来说会是灾难性的。</p><p>因此，选择 <ruby>其它选项<rt>Something else</rt></ruby>，单击 <ruby>继续<rt>Continue</rt></ruby> 按钮。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Something-else-ubuntu-installation.png" alt=""></p><p>分区表将显示所有现有的磁盘分区。到目前为止，我们仅有 NTFS 分区和我们之前压缩出来的可用分区。</p><p>针对 Ubuntu 22.04 ，我们将创建下面的分区：</p><ul><li><code>/boot</code>        –        1 GB</li><li><code>/home</code>        –        10 GB</li><li><code>/</code>            –        12 GB</li><li>交换分区        –         2 GB</li><li>EFI           –       300 MB</li></ul><p>为开始使用这些分区，单击 <ruby>可用空间<rt>Free Space</rt></ruby>分区下面的 “+” 符号。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Select-Free-Space-for-Ubuntu-22-04-Installation.png" alt=""></p><p>如图显示填写 <code>/boot</code> 分区的详细信息，然后单击 <ruby>确定<rt>OK</rt></ruby> 按钮。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Boot-Partition-Ubuntu-22-04-LTS.png" alt=""></p><p>接下来，具体指定 <code>/home</code> 分区，并单击 <ruby>确定<rt>OK</rt></ruby> 按钮。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Home-Partition-For-Ubuntu-22-04.png" alt=""></p><p>接下来，定义 <code>/</code>（根）分区，并单击 <ruby>确定<rt>OK</rt></ruby> 按钮。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Root-Partition-For-Ubuntu-22-04.png" alt=""></p><p>为定义交换空间，设置大小，并在 <ruby>使用为<rt>Use as</rt></ruby>：选项中选择 <ruby>交换区域<rt>Swap area</rt></ruby>。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Swap-Area-Ubuntu-22-04.png" alt=""></p><p>最后，如果你正在使用 UEFI 启动模式，那么创建一个 EFI 系统分区。我们将分配 300MB 到 EFI 分区。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/EFI-System-Partition-Ubuntu-22-04.png" alt=""></p><p>下图是一份我们的分区表的分区摘要：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Install-Now-Ubuntu-22-04.png" alt=""></p><p>为继续安装，单击 <ruby>现在安装<rt>Install Now</rt></ruby>。在下图显示的弹出窗口中，单击 <ruby>继续<rt>Continue</rt></ruby>来保存更改到磁盘。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Write-Changes-Disk-Ubuntu-22-04.png" alt=""></p><p>接下来，安装程序向导将自动侦测出你的位置，只需要单击 <ruby>继续<rt>Continue</rt></ruby> 按钮。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Location-for-Ubuntu-22-04-Installation.png" alt=""></p><p>接下来，通过具体指定姓名、计算机的名称和密码来创建一个登录用户。接下来单击 <ruby>继续<rt>Continue</rt></ruby> 按钮。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/UserName-Hostname-Ubuntu-22-04-lts-Installation.png" alt=""></p><p>此时，安装程序向导将复制所有的 Ubuntu 文件和软件包到手动创建的硬盘驱动器分区，并安装必要的软件包。</p><p>这个过程将需要很长一段时间，因此，要有耐心。在我们的实例中，它需要大约 30 分钟。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Installation-Progress-Ubuntu-22-04.png" alt=""></p><p>在安装过程完成后，单击 <ruby>立刻重新启动<rt>Restart Now</rt></ruby> 按钮来重新启动系统。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Restart-After-Ubuntu-22-04-LTS-Installation.png" alt=""></p><p>在这时，移除你的可启动 USB 驱动器，并按下回车键。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Remove-Installation-Media-after-Ubuntu-22-04-Installation.png" alt=""></p><p>在系统重新启动时，你将找到包括 Ubuntu 和 Windows 11 在内的各种选项。</p><p>选择 “Ubuntu” 来启动到你的新 Ubuntu 22.04 安装。要启动到 Windows 11，请选择标有 <ruby>Windows 恢复环境<rt>Windows Recovery Environment</rt></ruby> 的条目。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Dual-Boot-Grub-Bootloader-Screen-Ubuntu-22-04.png" alt=""></p><p>就这样。我们演示了如何双启动 Windows 11 和 Ubuntu 22.04。</p><hr>',65)),u("p",null,[t[5]||(t[5]=n("via: ",-1)),o(p,{href:"https://www.linuxtechi.com/dual-boot-ubuntu-22-04-and-windows-11/"},{default:r(()=>[...t[4]||(t[4]=[n("https://www.linuxtechi.com/dual-boot-ubuntu-22-04-and-windows-11/",-1)])]),_:1})]),u("p",null,[t[10]||(t[10]=n("作者：",-1)),o(p,{href:"https://www.linuxtechi.com/author/james/"},{default:r(()=>[...t[6]||(t[6]=[n("James Kiarie",-1)])]),_:1}),t[11]||(t[11]=n(" 选题：",-1)),o(p,{href:"https://github.com/lkxed"},{default:r(()=>[...t[7]||(t[7]=[n("lkxed",-1)])]),_:1}),t[12]||(t[12]=n(" 译者：",-1)),o(p,{href:"https://github.com/robsean"},{default:r(()=>[...t[8]||(t[8]=[n("robsean",-1)])]),_:1}),t[13]||(t[13]=n(" 校对：",-1)),o(p,{href:"https://github.com/wxy"},{default:r(()=>[...t[9]||(t[9]=[n("wxy",-1)])]),_:1})]),u("p",null,[t[16]||(t[16]=n("本文由 ",-1)),o(p,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[14]||(t[14]=[n("LCTT",-1)])]),_:1}),t[17]||(t[17]=n(" 原创编译，",-1)),o(p,{href:"https://linux.cn/"},{default:r(()=>[...t[15]||(t[15]=[n("Linux中国",-1)])]),_:1}),t[18]||(t[18]=n(" 荣誉推出",-1))])])}const S=l(w,[["render",b]]);export{x as __pageData,S as default};
